-- End-to-end checks use real source snapshots but roll back every test identity,
-- credential, review and configuration change. No operational validation is edited.
create temporary table qa_test_results(check_name text) on commit drop;
do $test$
declare checks jsonb:='[]'; admin_id uuid; user1 uuid:=gen_random_uuid(); user2 uuid:=gen_random_uuid(); staff_user uuid:=gen_random_uuid();
 analyst1 jsonb; analyst2 jsonb; pqr_analyst jsonb; response jsonb; review jsonb; results jsonb; job uuid; other_job uuid;
 supervisor_name text:='qa_test_'||substr(gen_random_uuid()::text,1,8); studies jsonb; before_pqr text; after_pqr text; before_source jsonb; today date:=(now() at time zone 'America/Bogota')::date;
begin
 begin
  select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by r.id),'')) into before_pqr from private.pqr_reviews r;
  if has_table_privilege('authenticated','private.qa_reviews','select,insert,update,delete') or has_function_privilege('anon','public.qa_api(text,jsonb)','execute') or has_function_privilege('authenticated','private.qa_refresh_day(date)','execute') then raise exception 'Unexpected QA privileges';end if;
  if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'qa_%' and c.relkind='r' and not c.relrowsecurity) then raise exception 'QA table missing RLS';end if;
  perform set_config('request.jwt.claim.sub','',true);
  begin perform public.qa_api('dashboard');raise exception 'Anonymous request accepted';exception when insufficient_privilege then null;end;
  checks:=checks||jsonb_build_array('QA data is private, sampling is owner-only, anonymous access is denied');
  select id into admin_id from public.profiles where is_active and role::text='admin' limit 1;
  if admin_id is null then raise exception 'Administrator required for test';end if;
  perform set_config('request.jwt.claim.sub',admin_id::text,true);
  response:=public.qa_api('dashboard');
  if (response->'stats'->>'target')::integer<>ceil((response->'stats'->>'eligible')::numeric*35/100) then raise exception 'Not exactly 35 percent of individual alerts';end if;
  if exists(select 1 from private.qa_reviews where jsonb_array_length(kpis)<>1 or original_results->(kpis->0->>'name')->>'status' is distinct from 'no_aplica') then raise exception 'Non-invalid alert included';end if;
  perform private.qa_refresh_today();perform private.qa_refresh_today();
  if exists(select 1 from private.qa_reviews group by day,source_key having count(*)>1) then raise exception 'Duplicate sample';end if;
  checks:=checks||jsonb_build_array('Global 35 percent rounds once; one review per invalid alert; refresh is idempotent');
  if exists(select 1 from private.qa_reviews r join public.audits a on a.id=r.source_audit_id where a.module<>'blocking' or (r.original_completed_at at time zone 'America/Bogota')::date<>r.day) then raise exception 'Wrong module or day';end if;
  checks:=checks||jsonb_build_array('Only Blocking completions from the original Colombian day are sampled');
  analyst1:=public.qa_api('create_analyst','{"name":"QA temporary one"}');
  analyst2:=public.qa_api('create_analyst','{"name":"QA temporary two"}');
  if analyst1->>'code' !~ '^QA-[A-Z2-9]{12}$' then raise exception 'Invalid QA code';end if;
  response:=public.qa_api('get_code',jsonb_build_object('id',analyst1->>'id'));
  if response->>'code'<>analyst1->>'code' then raise exception 'Copy code mismatch';end if;
  select jsonb_agg(jsonb_build_object('study',study,'analyst_id',analyst1->>'id','percentage',35)) into studies from private.qa_study_settings;
  perform public.qa_api('study_settings',jsonb_build_object('studies',studies,'percentage',35));
  perform public.qa_api('start_distribution');
  if exists(select 1 from private.qa_reviews where day=today and status='pending' and analyst_id is distinct from (analyst1->>'id')::uuid) then raise exception 'Study owner assignment failed';end if;
  select id into job from private.qa_reviews where analyst_id=(analyst1->>'id')::uuid and status='pending' limit 1;
  if job is null then raise exception 'No live source alerts for integration check';end if;
  checks:=checks||jsonb_build_array('QA analyst creation, recoverable encrypted codes and study-based assignments work');
  perform public.pqr_api('create_supervisor',jsonb_build_object('name','Shared test supervisor','username',supervisor_name,'password','Qa-temporary-2026!'));
  insert into auth.users(id,aud,role,is_anonymous) values(user1,'authenticated','authenticated',true),(user2,'authenticated','authenticated',true),(staff_user,'authenticated','authenticated',true);
  perform set_config('request.jwt.claim.sub',staff_user::text,true);
  response:=public.pqr_login('supervisor',supervisor_name,'Qa-temporary-2026!');
  if response->>'role'<>'supervisor' then raise exception 'Supervisor login failed';end if;
  response:=public.qa_api('dashboard');
  if response->'context'->>'role'<>'supervisor' then raise exception 'Shared supervisor cannot open QA sheet';end if;
  response:=public.pqr_api('context');
  if response->>'role'<>'supervisor' then raise exception 'QA sheet invalidated PQR session';end if;
  checks:=checks||jsonb_build_array('Same supervisor session opens PQR and QA; switching does not revoke PQR');
  perform set_config('request.jwt.claim.sub',user1::text,true);
  response:=public.qa_login('analyst','',analyst1->>'code');
  if response->>'role'<>'analyst' then raise exception 'QA login failed';end if;
  begin perform public.pqr_api('dashboard');raise exception 'QA analyst accessed PQR';exception when insufficient_privilege then null;end;
  begin perform public.qa_api('create_analyst','{"name":"Unauthorized"}');raise exception 'Analyst managed staff';exception when insufficient_privilege then null;end;
  select to_jsonb(a) into before_source from public.audits a join private.qa_reviews r on r.source_audit_id=a.id where r.id=job;
  review:=public.qa_api('start',jsonb_build_object('id',job));
  begin perform public.qa_api('save',jsonb_build_object('id',job,'version',-1,'results','{}'::jsonb));raise exception 'Stale version accepted';exception when serialization_failure then null;end;
  begin perform public.qa_api('save',jsonb_build_object('id',job,'version',(review->>'version')::integer,'complete',true,'results','{}'::jsonb));raise exception 'Empty completion accepted';exception when raise_exception then if sqlerrm='Empty completion accepted' then raise;end if;end;
  results:=jsonb_build_object(review->'kpis'->0->>'name',jsonb_build_object('evaluation','incorrect','correct_decision','aplica','comment',''));
  review:=public.qa_api('save',jsonb_build_object('id',job,'version',(review->>'version')::integer,'results',results,'complete',true));
  if review->>'status'<>'completed' or review->>'verdict'<>'errors' then raise exception 'QA completion failed';end if;
  if (select to_jsonb(a) from public.audits a join private.qa_reviews r on r.source_audit_id=a.id where r.id=job) is distinct from before_source then raise exception 'Source validation changed';end if;
  response:=public.qa_api('export');
  if not exists(select 1 from jsonb_array_elements(response->'reviews') r where r->>'id'=job::text and r->'review_results'=results) then raise exception 'Export missing review';end if;
  checks:=checks||jsonb_build_array('QA analyst can complete and export; version and completion guards work; original validation is preserved');
  perform set_config('request.jwt.claim.sub',admin_id::text,true);
  select jsonb_agg(jsonb_build_object('study',study,'analyst_id',analyst2->>'id','percentage',35)) into studies from private.qa_study_settings;
  perform public.qa_api('study_settings',jsonb_build_object('studies',studies,'percentage',35));
  if (select analyst_id from private.qa_reviews where id=job) is distinct from (analyst1->>'id')::uuid then raise exception 'Completed review reassigned';end if;
  select id into other_job from private.qa_reviews where analyst_id=(analyst2->>'id')::uuid and status='pending' limit 1;
  if other_job is null then raise exception 'Changed owner did not receive pending work';end if;
  perform set_config('request.jwt.claim.sub',user1::text,true);
  begin perform public.qa_api('detail',jsonb_build_object('id',other_job));raise exception 'Cross analyst read accepted';exception when insufficient_privilege then null;end;
  perform set_config('request.jwt.claim.sub',admin_id::text,true);
  perform public.qa_api('reset_code',jsonb_build_object('id',analyst1->>'id'));
  perform set_config('request.jwt.claim.sub',user1::text,true);
  if private.qa_context() is not null then raise exception 'Code reset did not revoke session';end if;
  perform set_config('request.jwt.claim.sub',admin_id::text,true);
  perform public.qa_api('delete_analyst',jsonb_build_object('id',analyst1->>'id'));
  if not exists(select 1 from private.qa_reviews where id=job and status='completed') then raise exception 'History lost on deletion';end if;
  perform public.qa_api('restore_analyst',jsonb_build_object('id',analyst1->>'id'));
  if exists(select 1 from private.qa_analysts where id=(analyst1->>'id')::uuid and active) then raise exception 'Restored analyst unexpectedly active';end if;
  checks:=checks||jsonb_build_array('Reassignment preserves completed history, other analysts are isolated, rotation/deletion/restore protect access');
  select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by r.id),'')) into after_pqr from private.pqr_reviews r;
  if before_pqr is distinct from after_pqr then raise exception 'QA changed existing PQR reviews';end if;
  checks:=checks||jsonb_build_array('Existing PQR reviews are byte-for-byte unchanged');
  raise exception using errcode='P0002',message='QA_TEST_FINISHED';
 exception when no_data_found then if sqlerrm<>'QA_TEST_FINISHED' then raise;end if;end;
 insert into pg_temp.qa_test_results select jsonb_array_elements_text(checks);
end;$test$;
select jsonb_agg(check_name) as checks from pg_temp.qa_test_results;
